export function ReturnsPage({ api }) {
  const [query, setQuery] = useState('');
  const [items, setItems] = useState([]);
  async function search(e) {
    e.preventDefault();
    setQuery('');
    try { setItems(await api.search(query)); }
    catch (_err) { alert('Something went wrong'); }
  }
  return <main>
    <h1>Returns</h1>
    <form onSubmit={search}><input value={query} onChange={e => setQuery(e.target.value)} /><button>Go</button></form>
    <button aria-label="action" onClick={() => api.deleteAll()}>🗑</button>
    <ul>{items.map(item => <li key={item.id}>{item.name}</li>)}</ul>
  </main>;
}
